  <header>
    <div class="brand">{{BUSINESS_NAME}} Shop</div>
    <nav>
      <a href="index.html">Explore</a>
      <a href="services.html">Therapies</a>
      <a href="blends.html">Elixirs</a>
      <a href="shop.html">Shop</a>
    </nav>
  </header>

  <main class="container">
    <div class="grid">
      <section>
        <div style="display:flex;justify-content:space-between;align-items:center">
          <h2 style="margin:0">Available items</h2>
          <div class="muted">We include dilution guidance and safety notes with each product.</div>
        </div>

        <div style="margin-top:12px;display:flex;align-items:center;gap:12px">
          <div class="switch" role="tablist" aria-label="Price view">
            <button id="singleBtn" class="active">One-time</button>
            <button id="subBtn">Subscription</button>
          </div>
          <div class="muted">Toggle to compare single purchase vs subscription price.</div>
        </div>

        <div class="products" id="productGrid" style="margin-top:12px">
          <div class="prod" data-one="18" data-sub="15">
            <h4>Citrus Lift Roll-on</h4>
