  <script>
    (function(){
      // pricing toggle for shop with animated numbers per product
      const singleBtn = document.getElementById('singleBtn');
      const subBtn = document.getElementById('subBtn');
      const prods = Array.from(document.querySelectorAll('.prod'));
      let plan = 'one';

      function animatePrice(el, start, end){
        const priceEl = el.querySelector('[data-price]');
        const dur = 360; const s = performance.now();
        function step(t){
          const p = Math.min(1,(t-s)/dur);
          const ease = 1 - Math.pow(1-p,3);
          const val = Math.round(start + (end-start)*ease);
          priceEl.textContent = '$' + val;
          if(p<1) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      function setPlan(to){
        if(to===plan) return; plan = to;
        prods.forEach(p=>{
          const one = parseInt(p.getAttribute('data-one'),10);
          const sub = parseInt(p.getAttribute('data-sub'),10);
          const target = (to==='one')?one:sub;
          const current = parseInt(p.querySelector('[data-price]').textContent.replace('$',''),10);
          animatePrice(p,current,target);
        });
      }

      singleBtn.addEventListener('click',function(){ singleBtn.classList.add('active'); subBtn.classList.remove('active'); setPlan('one'); });
      subBtn.addEventListener('click',function(){ subBtn.classList.add('active'); singleBtn.classList.remove('active'); setPlan('sub'); });

      // small cart placeholder
      const cartSummary = document.getElementById('cartSummary');
      document.querySelectorAll('.buy').forEach(btn=>{
        btn.addEventListener('click',function(e){ e.preventDefault(); cartSummary.textContent = 'Added an item — proceed to checkout to complete purchase. Prices include safety notes.'; cartSummary.animate([{opacity:1},{opacity:0.6},{opacity:1}],{duration:320}); });
      });

      // init
      prods.forEach(p=>{ const priceEl = p.querySelector('[data-price]'); priceEl.textContent = '$' + p.getAttribute('data-one'); });
    })();
  </script>
